use super::*;
use crate::income::IncomeSource;
use crate::txn::days_between;

/// A source is ended, not merely late, once it is overdue by several of its own periods.
pub(crate) fn is_lapsed(s: &IncomeSource, as_of: &str, lapse_factor: f64) -> bool {
    match cadence_days(s.cadence) {
        None => false,
        Some(period) => days_between(&s.last_seen, as_of) as f64 > period * lapse_factor,
    }
}
